<?php
declare(strict_types=1); require_once __DIR__.'/../includes/layout.php'; require_admin();$q=trim((string)($_GET['q']??''));$s=db()->prepare("SELECT u.*,COUNT(DISTINCT rs.id) reservations,COUNT(DISTINCT r.id) rentals FROM users u LEFT JOIN reservations rs ON rs.user_id=u.id LEFT JOIN rentals r ON r.user_id=u.id WHERE u.role='member' AND (u.fullname LIKE ? OR u.username LIKE ? OR u.phone LIKE ?) GROUP BY u.id ORDER BY u.created_at DESC");$s->execute(array_fill(0,3,"%$q%"));$rows=$s->fetchAll();page_start('สมาชิก','members'); ?>
<div class="page-head"><div><h1>สมาชิก</h1><p>ข้อมูลบัญชีสมาชิกและจำนวนรายการใช้งาน</p></div></div><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="ค้นหาชื่อ ชื่อผู้ใช้ หรือโทรศัพท์"><button class="btn">ค้นหา</button></form><section class="panel"><div class="table-wrap"><table><thead><tr><th>ชื่อสมาชิก</th><th>ชื่อผู้ใช้</th><th>โทรศัพท์</th><th>การจอง</th><th>การเช่า</th><th>สมัครเมื่อ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['fullname'])?></td><td><?=e($r['username'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['reservations'])?></td><td><?=e($r['rentals'])?></td><td><?=thai_date($r['created_at'],true)?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="6" class="empty">ไม่พบสมาชิก</td></tr><?php endif?></tbody></table></div></section>
<?php page_end(); ?>
